import re

import perceivo

_PLATFORMS = ("telegram", "slack", "discord", "teams")
_SEVERITIES = ("info", "warning", "critical")
_FALSY = ("false", "0", "no", "off")

# ${field} placeholders in the message, title and action URL are filled from
# the inbound request_data. An unknown field is left as written, so a typo is
# visible in the delivered message rather than silently blanked.
_PLACEHOLDER = re.compile(r"\$\{(\w+)\}")


def _interpolate(template: str, data: dict) -> str:
    """Replace each ${field} with str(data[field]) when that field is present."""

    def _replace(match):
        value = data.get(match.group(1))
        return match.group(0) if value is None else str(value)

    return _PLACEHOLDER.sub(_replace, template)


def _param(name: str, default: str = "") -> str:
    return str(perceivo.params.get(name, default) or default).strip()


def _enabled() -> bool:
    value = perceivo.params.get("enabled", True)
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() not in _FALSY


def _fields(data: dict):
    """The optional key/value block rendered under the message, as strings."""
    fields = data.get("fields")
    if not isinstance(fields, dict) or not fields:
        return None
    return {str(key): str(value) for key, value in fields.items()}


@perceivo.tool
async def chat_channel_gateway(input: perceivo.primitives.ToolInput) -> perceivo.primitives.ToolOutput:
    """Send one message to one chat platform.

    The platform, recipient and message are node parameters; the inbound
    request_data only fills ${field} placeholders and supplies the optional
    `fields` block. The platform credential is the `credentials` secret, passed
    to the SDK by NAME -- this script never sees its id or its value.

    A misconfigured node raises ValueError, and a failed dispatch raises from
    `perceivo.alerts.send_direct`. Neither is caught: a message that did not
    arrive must fail the run, never be reported as sent. The one outcome other
    than "sent" is "skipped", when the Enabled switch is off.
    """
    data = input.request_data or {}
    if not isinstance(data, dict):
        data = {}

    platform = _param("platform").lower()

    if not _enabled():
        perceivo.log.info("Chat Channel Gateway: disabled, nothing sent", channel=platform)
        return perceivo.primitives.ToolOutput(
            response_data={
                "channel": platform,
                "status": "skipped",
                "delivery_id": "",
                "platform_status": "",
                "reason": "channel_disabled",
            },
        )

    if platform not in _PLATFORMS:
        raise ValueError(f"Platform is {platform!r}. Choose one of: {', '.join(_PLATFORMS)}.")

    recipient = _param("recipient")
    if not recipient:
        raise ValueError(
            "Recipient is empty. Set the chat id (Telegram), channel id (Slack, "
            "Discord) or webhook URL (Teams)."
        )

    message = _interpolate(_param("message"), data).strip()
    if not message:
        raise ValueError("Message is empty. Set the Message parameter.")

    severity = _param("severity", "info").lower()
    if severity not in _SEVERITIES:
        raise ValueError(f"Severity is {severity!r}. Choose one of: {', '.join(_SEVERITIES)}.")

    title = _interpolate(_param("title"), data) or None
    action_url = _interpolate(_param("action_url"), data) or None
    action_label = _param("action_label", "Open") if action_url else None

    perceivo.log.info(
        f"Chat Channel Gateway: sending to {platform}",
        channel=platform,
        message_chars=len(message),
        has_title=bool(title),
        has_action=bool(action_url),
        severity=severity,
    )

    delivery = await perceivo.alerts.send_direct(
        medium=platform,
        recipient=recipient,
        credentials_secret="credentials",
        message=message,
        title=title,
        action_url=action_url,
        action_label=action_label,
        severity=severity,
        fields=_fields(data),
    )

    # send_direct raises on a failed dispatch; this guards the one remaining
    # way to report an undelivered message as sent.
    if not delivery.delivered:
        raise RuntimeError(
            f"Chat Channel Gateway: {platform} did not confirm delivery "
            f"(status {delivery.status!r})."
        )

    delivery_id = delivery.delivery_id or ""
    perceivo.log.info(
        f"Chat Channel Gateway: sent to {platform}",
        channel=platform,
        delivery_id=delivery_id,
    )

    return perceivo.primitives.ToolOutput(
        response_data={
            "channel": platform,
            "status": "sent",
            "delivery_id": delivery_id,
            "platform_status": delivery.status or "",
            "reason": "",
        },
    )
